  "PUT /api/v1/settings/working-week": { body: z.input<typeof settings.WorkingWeekSave>; query: never; params: never; response: z.output<typeof settings.WorkingWeek> };
  "GET /api/v1/users": { body: never; query: z.input<typeof users.UserListQuery>; params: never; response: z.output<typeof users.UserPage> };
